export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は外へ出た。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "人造石の床に足が触れた瞬間、気づいた——音がない。小さいのではない。ないのだ。スニーカーのゴム底が床を踏めば、少しは擦れる音が、少しは響きがあるはずなのに、何もない。写真の中へ歩み入ったようだった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）振り返っちゃだめ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "背後で、エレベーターのドアが閉まり始めた。その音だけは聞こえた。左の扉が半拍遅れて、ガタン、ガタン、と閉じる。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それからケーブルの音。長く、重く。下へ。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "両側の鉄の扉はどれも閉ざされていて、部屋番号は赤い光に食われ、空白だけが並んでいた。彼女はその前を一枚ずつ通り過ぎ、そして足を止めた。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三つ目の扉。灰色の玄関マットの角には、洗濯機に潰されてできたへこみがある。靴箱の上には白いキャンバススニーカーが一足、紐が靴の中に押し込んである——彼女の癖で、方芮に一年じゅう小言を言われてきた。ドアノブにはドライフラワーのリース。方芮がフリマで買ってきて、家に帰ってから色がひどくダサいと気づいたものだ。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）うちだ。九階の三号室。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）ここは十階だ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "扉の向こうから、音がした。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "この廊下に足を踏み入れてから、初めて聞いた音だった。鉄の扉越しにくぐもって、水を一枚隔てたように聞こえる。方芮の笑い声だった。泣いたあとの鼻声まじりの。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "ほんっとに怖かったんだからね？　電話の途中で急に黙っちゃうし、ロビーで十分も待ったんだよ……", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "もう一つの声がそれに答えた。少しかすれていて、語尾が下がる。寝不足みたいな声。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「ちゃんと帰ってきたでしょ」", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女自身の声だった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は手を上げて扉を叩いた。指の関節が鉄にぶつかる。骨が痛むほど強く。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "音はしなかった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "芮芮！", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Scared },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "叫んだ。喉が震えるのがわかった。肺の空気が残らず押し出されるのがわかった。それなのに、廊下には何も響かない。その名前が口を離れた途端、誰かに受け取られ、持ち去られてしまったかのように。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "なんか声へんじゃない？", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「風邪かも」と、その声は言った。「エレベーターの中、寒かったから」", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "足音が扉のそばまで近づいてくる。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアスコープが一瞬暗くなった。誰かが内側から外を覗いている。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "許念は赤い光の中に立っていた。自分の家の前に。その小さな丸いガラスから、五十センチも離れていない場所に。後ずさりもせず、振り返りもしなかった。それが暗くなり、また明るく戻るのを、ただ見ていた。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「誰もいない」と、彼女の声が言った。「たぶん隣じゃない？」", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "足音が遠ざかっていく。リビングのテレビがつき、効果音の笑い声が湧き上がった。波のように、笑っては静まり、静まってはまた笑う。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）同じところ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "廊下の赤い光は変わらない。窓の外も変わらない。背後の、彼女が振り返って見てはいけない方角も、何ひとつ変わらなかった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "背後のずっと遠くで、誰かがそっと呼んだ。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「念念」", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "方芮の声だった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）名前を呼ばれても、振り返って返事をしてはいけない。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は冷たい鉄の扉に額を押し当てた。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "扉の向こうで、誰かが彼女の声で「おやすみ」と言った。", background: Background.Branch_1b_B1b_Act4_S0 },
];
